INSERT INTO book_versions(book_id,version,title,author,genre,rights_status,rights_basis,content_hash,object_key) VALUES
 ('stationmaster', '1', 'Станционный смотритель', 'Александр Пушкин', 'Классика', 'approved', 'Русский оригинал — общественное достояние. Текст: Интернет-библиотека Алексея Комарова, по собранию сочинений А. С. Пушкина в 6 т., т. 4 (Правда, 1969). Страница источника указывает свободное использование произведения. Навигация, оформление сайта и сноски не включены; пробелы нормализованы, курсив приведён к обычному тексту, стихотворные строки эпиграфов соединены пробелами. Обложка: Титульный лист сборника «Повести покойного Ивана Петровича Белкина», Санкт-Петербург, 1831. Wikimedia Commons, Public Domain. Другое издание, чем источник текста; изображение не изменено.', 'b557173e3db9abcd541eab7360bcbc5e6802d8369ef18a3ad366ad80aea677fb', '/books/stationmaster.json'),
